-- Bounded annual national EPA snapshot. No individual records.
CREATE TABLE IF NOT EXISTS public.wage_distribution_snapshot (
 scope text PRIMARY KEY CHECK (scope = 'epa-national'),
 metadata jsonb NOT NULL CHECK (metadata->>'version' = 'epa-monthly-national-2021-v1' AND jsonb_typeof(metadata->'years') = 'array' AND jsonb_array_length(metadata->'years') BETWEEN 1 AND 30)
);
ALTER TABLE public.wage_distribution_snapshot ENABLE ROW LEVEL SECURITY;
CREATE POLICY wage_distribution_public_read ON public.wage_distribution_snapshot FOR SELECT TO anon, authenticated USING (true);
GRANT SELECT ON public.wage_distribution_snapshot TO anon, authenticated;
GRANT ALL ON public.wage_distribution_snapshot TO service_role;
